    weight_lanes = (2, 3, 6, 7)
    self.partition_loops = set()
    first_wave_events = {}
    with self.loop(name + "preload", 0, 1):
        for shard in range(32):
            self.active_shard = shard
            if shard >= 16:
                self.emit("WAIT", wg=self.group_name(shard), events=first_wave_events[shard - 16])
